content.css:
.kpi-card {
  position: absolute;
  inset: 0;
  box-sizing: border-box;
  padding: 10px 12px 8px;
  display: flex;
  flex-direction: column;
  font-family: "Segoe UI", wf_segoe-ui_normal, helvetica, arial, sans-serif;
  overflow: hidden;
  user-select: none;
}
.kpi-card.kpi-no-chart {
  justify-content: center;
}
.kpi-card.kpi-no-chart .kpi-delta {
  margin-top: 6px;
  font-size: 12px;
}
.kpi-title {
  font-weight: 600;
  letter-spacing: 0.02em;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.kpi-value {
  font-weight: 600;
  line-height: 1.15;
  margin-top: 2px;
  white-space: nowrap;
  font-variant-numeric: tabular-nums;
}
.kpi-delta {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-top: 4px;
  min-height: 18px;
  font-size: 11px;
  white-space: nowrap;
  overflow: hidden;
}
.kpi-badge {
  flex: 0 0 auto;
  padding: 1px 7px;
  border-radius: 10px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}
.kpi-delta-label {
  color: #605E5C;
  overflow: hidden;
  text-overflow: ellipsis;
}
.kpi-chart {
  position: relative;
  flex: 1 1 auto;
  min-height: 0;
  margin-top: 6px;
  cursor: crosshair;
}
.kpi-chart svg {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  overflow: visible;
}
.kpi-line {
  fill: none;
  stroke-width: 2;
  stroke-linecap: round;
  stroke-linejoin: round;
}
.kpi-pulse {
  fill: none;
  stroke-width: 1.5;
}
.kpi-hover-dot {
  fill: #fff;
  stroke-width: 2;
}
.kpi-hover {
  position: absolute;
  top: -2px;
  left: 0;
  padding: 2px 6px;
  font-size: 10px;
  color: #fff;
  background: rgba(37, 36, 35, 0.88);
  border-radius: 4px;
  white-space: nowrap;
  pointer-events: none;
}
.kpi-period {
  margin-top: 2px;
  font-size: 10px;
  color: #8A8886;
}
.kpi-empty {
  position: absolute;
  inset: 0;
  display: none;
  align-items: center;
  justify-content: center;
  padding: 12px;
  text-align: center;
  white-space: pre-line;
  font: 12px "Segoe UI", wf_segoe-ui_normal, helvetica, arial, sans-serif;
  color: #605E5C;
}
